CREATE OR REPLACE FUNCTION public.admin_bulk_delete_budget_requests(_session_token text, _request_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_admin_id uuid;
  v_admin_name text;
  v_rec record;
  v_audit_desc text;
  v_liq_ids uuid[];
  v_deleted_count int;
BEGIN
  SELECT vat.admin_id INTO v_admin_id
  FROM public.validate_admin_session_token(_session_token) vat
  LIMIT 1;

  IF v_admin_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Admin account is not authorized.');
  END IF;

  SELECT display_name INTO v_admin_name
  FROM public.admin_accounts
  WHERE id = v_admin_id;

  IF v_admin_name IS NULL THEN
    v_admin_name := 'Admin';
  END IF;

  IF _request_ids IS NULL OR array_length(_request_ids, 1) IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No request IDs provided.');
  END IF;

  SELECT array_agg(id) INTO v_liq_ids
  FROM public.liquidation_reports
  WHERE budget_request_id = ANY(_request_ids);

  -- Log audit entries for deleted records if enabled
  IF public.is_audit_logging_enabled('deletion') THEN
    FOR v_rec IN
      SELECT id, organization_id, activity_title, status, requested_amount, approved_amount, released_amount
      FROM public.budget_requests
      WHERE id = ANY(_request_ids)
    LOOP
      IF v_rec.status IN ('budget_released', 'completed') THEN
        v_audit_desc := format(
          'Admin %s permanently deleted budget request "%s" (Status: %s, Requested: ₱%s, Approved: ₱%s, Released: ₱%s). Note: This later-stage financial record and its associated liquidation reports/files were intentionally deleted.',
          v_admin_name,
          v_rec.activity_title,
          v_rec.status,
          to_char(COALESCE(v_rec.requested_amount, 0), 'FM999,999,999,990.00'),
          to_char(COALESCE(v_rec.approved_amount, 0), 'FM999,999,999,990.00'),
          to_char(COALESCE(v_rec.released_amount, 0), 'FM999,999,999,990.00')
        );
      ELSE
        v_audit_desc := format(
          'Admin %s deleted budget request "%s" (Amount: ₱%s, Lifecycle: %s).',
          v_admin_name,
          v_rec.activity_title,
          to_char(COALESCE(v_rec.requested_amount, 0), 'FM999,999,999,990.00'),
          v_rec.status
        );
      END IF;

      INSERT INTO public.activity_logs (
        actor_user_id,
        organization_id,
        action,
        related_type,
        related_id,
        description,
        metadata
      ) VALUES (
        v_admin_id,
        v_rec.organization_id,
        'deleted_budget_request',
        'budget_request',
        v_rec.id,
        v_audit_desc,
        public.extract_audit_request_metadata()
      );
    END LOOP;
  END IF;

  DELETE FROM public.notifications
  WHERE (related_type = 'budget_request' AND related_id = ANY(_request_ids))
     OR (v_liq_ids IS NOT NULL AND related_type = 'liquidation_report' AND related_id = ANY(v_liq_ids));

  DELETE FROM public.budget_requests
  WHERE id = ANY(_request_ids);

  GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'deleted_count', v_deleted_count,
    'deleted_ids', _request_ids
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_get_budget_monitoring_summary(_session_token text, _fiscal_year integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _admin_id uuid;
  _allocation RECORD;
  _total_fy_budget numeric := NULL;
  _statutory_baseline_notes text := NULL;
  _is_configured boolean := false;
  _approved_budget numeric := 0;
  _released_budget numeric := 0;
  _liquidated_budget numeric := 0;
  _pending_disbursement numeric := 0;
  _active_in_field numeric := 0;
  _remaining_headroom numeric := NULL;
  _deficit_amount numeric := 0;
  _is_deficit boolean := false;
  _category_breakdown jsonb := '[]'::jsonb;
  _total_requests integer := 0;
  _released_requests integer := 0;
  _liquidated_requests integer := 0;
BEGIN
  -- Authenticate admin session
  SELECT vat.admin_id
  INTO _admin_id
  FROM public.validate_admin_session_token(_session_token) vat
  LIMIT 1;

  IF _admin_id IS NULL THEN
    RAISE EXCEPTION 'Admin account is not authorized.';
  END IF;

  -- 1. Fetch configured annual allocation for the target fiscal year
  SELECT total_amount, statutory_baseline_notes, is_active
  INTO _allocation
  FROM public.annual_budget_allocations
  WHERE fiscal_year = _fiscal_year
  LIMIT 1;

  IF FOUND THEN
    _total_fy_budget := _allocation.total_amount;
    _statutory_baseline_notes := _allocation.statutory_baseline_notes;
    _is_configured := true;
  END IF;

  -- 2. Aggregate approved budget requests belonging to this fiscal year
  -- Allowed approved lifecycle statuses: approved_for_ftf_green, hard_copy_submitted, budget_released, completed
  SELECT
    COALESCE(SUM(COALESCE(approved_amount, requested_amount, 0)), 0),
    COUNT(*)
  INTO _approved_budget, _total_requests
  FROM public.budget_requests
  WHERE fiscal_year = _fiscal_year
    AND status IN ('approved_for_ftf_green', 'hard_copy_submitted', 'budget_released', 'completed');

  -- 3. Aggregate released budget requests belonging to this fiscal year
  SELECT
    COALESCE(SUM(COALESCE(released_amount, 0)), 0),
    COUNT(*)
  INTO _released_budget, _released_requests
  FROM public.budget_requests
  WHERE fiscal_year = _fiscal_year
    AND status IN ('budget_released', 'completed');

  -- 4. Aggregate liquidated budget requests belonging to this fiscal year
  -- Sums the released_amount of budget_requests with completed_liquidated liquidation_reports
  SELECT
    COALESCE(SUM(COALESCE(br.released_amount, 0)), 0),
    COUNT(DISTINCT lr.id)
  INTO _liquidated_budget, _liquidated_requests
  FROM public.liquidation_reports lr
  JOIN public.budget_requests br ON lr.budget_request_id = br.id
  WHERE br.fiscal_year = _fiscal_year
    AND lr.status = 'completed_liquidated';

  -- 5. Derived financial execution metrics
  _pending_disbursement := GREATEST(_approved_budget - _released_budget, 0);
  _active_in_field := GREATEST(_released_budget - _liquidated_budget, 0);

  IF _is_configured THEN
    -- Correct statutory headroom: Total FY Budget - Approved Budget
    _remaining_headroom := _total_fy_budget - _approved_budget;
    IF _remaining_headroom < 0 THEN
      _is_deficit := true;
      _deficit_amount := ABS(_remaining_headroom);
    ELSE
      _is_deficit := false;
      _deficit_amount := 0;
    END IF;
  ELSE
    _remaining_headroom := NULL;
    _is_deficit := false;
    _deficit_amount := 0;
  END IF;

  -- 6. Category breakdown by purpose for this fiscal year
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'category', cat_row.category,
        'approved_amount', cat_row.cat_approved,
        'released_amount', cat_row.cat_released,
        'request_count', cat_row.req_count
      )
      ORDER BY cat_row.cat_approved DESC, cat_row.category ASC
    ),
    '[]'::jsonb
  )
  INTO _category_breakdown
  FROM (
    SELECT
      COALESCE(NULLIF(TRIM(purpose_category), ''), 'General / Uncategorized') AS category,
      SUM(COALESCE(approved_amount, requested_amount, 0)) AS cat_approved,
      SUM(CASE WHEN status IN ('budget_released', 'completed') THEN COALESCE(released_amount, 0) ELSE 0 END) AS cat_released,
      COUNT(*) AS req_count
    FROM public.budget_requests
    WHERE fiscal_year = _fiscal_year
      AND status IN ('approved_for_ftf_green', 'hard_copy_submitted', 'budget_released', 'completed')
    GROUP BY COALESCE(NULLIF(TRIM(purpose_category), ''), 'General / Uncategorized')
  ) cat_row;

  RETURN jsonb_build_object(
    'fiscal_year', _fiscal_year,
    'is_configured', _is_configured,
    'total_fy_budget', _total_fy_budget,
    'statutory_baseline_notes', _statutory_baseline_notes,
    'approved_budget', _approved_budget,
    'released_budget', _released_budget,
    'liquidated_budget', _liquidated_budget,
    'pending_disbursement', _pending_disbursement,
    'active_in_field', _active_in_field,
    'remaining_headroom', _remaining_headroom,
    'is_deficit', _is_deficit,
    'deficit_amount', _deficit_amount,
    'total_requests', _total_requests,
    'released_requests', _released_requests,
    'liquidated_requests', _liquidated_requests,
    'category_breakdown', _category_breakdown
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.extract_audit_request_metadata()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _headers jsonb;
  _meta jsonb := '{}'::jsonb;
  _ua text;
  _ip text;
BEGIN
  BEGIN
    _headers := current_setting('request.headers', true)::jsonb;
  EXCEPTION WHEN OTHERS THEN
    _headers := NULL;
  END;

  IF _headers IS NOT NULL THEN
    -- User-Agent
    IF public.is_audit_logging_enabled('metadata_user_agent') THEN
      _ua := coalesce(_headers->>'user-agent', _headers->>'User-Agent');
      IF _ua IS NOT NULL AND trim(_ua) <> '' THEN
        _meta := _meta || jsonb_build_object('user_agent', trim(_ua));
      END IF;
    END IF;

    -- Client IP (reads standard proxy headers forwarded by Supabase / Cloudflare)
    IF public.is_audit_logging_enabled('metadata_ip') THEN
      _ip := coalesce(
        _headers->>'x-forwarded-for',
        _headers->>'cf-connecting-ip',
        _headers->>'x-real-ip'
      );
      IF _ip IS NOT NULL AND trim(_ip) <> '' THEN
        _ip := trim(split_part(_ip, ',', 1));
        _meta := _meta || jsonb_build_object('ip_address', _ip);
      END IF;
    END IF;
  END IF;

  RETURN _meta;
END;
$function$

CREATE OR REPLACE FUNCTION public.is_audit_logging_enabled(_category text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _setting_key text;
  _val jsonb;
BEGIN
  CASE lower(trim(coalesce(_category, '')))
    WHEN 'login' THEN _setting_key := 'audit.log_admin_login';
    WHEN 'logout' THEN _setting_key := 'audit.log_admin_logout';
    WHEN 'create' THEN _setting_key := 'audit.log_record_creation';
    WHEN 'update' THEN _setting_key := 'audit.log_record_updates';
    WHEN 'approval' THEN _setting_key := 'audit.log_approvals_rejections';
    WHEN 'deletion' THEN _setting_key := 'audit.log_deletions';
    WHEN 'permission' THEN _setting_key := 'audit.log_permission_changes';
    WHEN 'config' THEN _setting_key := 'audit.log_config_changes';
    WHEN 'metadata_user_agent' THEN _setting_key := 'audit.include_user_agent';
    WHEN 'metadata_ip' THEN _setting_key := 'audit.include_ip_metadata';
    ELSE
      RETURN true;
  END CASE;

  SELECT value_json INTO _val
  FROM public.admin_system_settings
  WHERE setting_key = _setting_key;

  IF _val IS NULL THEN
    IF _setting_key = 'audit.include_ip_metadata' THEN
      RETURN false;
    ELSE
      RETURN true;
    END IF;
  END IF;

  RETURN coalesce((_val)::boolean, true);
END;
$function$
